mapper.select:
SELECT id, event_id, tenant_id, requested_by, approved_by, incident_reference,
       status, requested_at, expires_at, executed_at
FROM ainer_identity_access_event_replay_request
WHERE tenant_id = #{tenantId}
  AND id = #{requestId}
FOR UPDATE

mapper.update:
UPDATE ainer_identity_access_event_replay_request
SET status = 'EXECUTED',
    approved_by = #{approvedBy},
    executed_at = #{executedAt}
WHERE id = #{requestId}
  AND status = 'REQUESTED'
  AND expires_at > #{executedAt}
  AND requested_by <> #{approvedBy}

